//
// e2ee_test.js — browser-side E2EE crypto (client/web/e2ee.js).
//
// Two kinds of assertion:
//
//   1. Cross-language vectors. tests/fixtures/e2ee-vectors.json was generated by
//      the Elixir implementation (scripts/gen-e2ee-vectors.exs) and is
//      re-derived here with WebCrypto. If the two halves of the protocol ever
//      disagree, this fails — which is the only way to notice before a client
//      ships and cannot talk to the server.
//
//   2. Behaviour the vectors cannot express: tampering, replay, epoch changes.
//
// Runs under Deno (`deno task test`) and under Node 22+ (`node --test`-less
// shim), because both expose WebCrypto.

import assert from "node:assert";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import * as E2EE from "../e2ee.js";

const here = dirname(fileURLToPath(import.meta.url));
const vectors = JSON.parse(readFileSync(join(here, "fixtures", "e2ee-vectors.json"), "utf8"));

const hex = E2EE.fromHex;
const hexOut = E2EE.toHex;

// ---------------------------------------------------------------------------
// Is the platform capable at all?
// ---------------------------------------------------------------------------

Deno.test("E2EE.isSupported reports WebCrypto availability", () => {
  assert.strictEqual(E2EE.isSupported(), true);
});

// ---------------------------------------------------------------------------
// 1. Cross-language vectors
// ---------------------------------------------------------------------------

Deno.test("vectors: the RFC 7748 private key imports through the PKCS#8 wrapper", async () => {
  // WebCrypto has no "derive public from private" and will not import a raw
  // X25519 private key, so the wrapper is the only thing to check here: it must
  // round-trip byte-for-byte. Agreement with the fixture's public key is
  // established by the pairwise test below.
  const priv = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_a), { extractable: true });
  assert.strictEqual(hexOut(await E2EE.exportPrivateKey(priv)), vectors.rfc7748_private_a);

  // A key imported without the flag must not be exportable.
  const sealed = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_a));
  await assert.rejects(E2EE.exportPrivateKey(sealed));
});

Deno.test("vectors: pairwiseKey matches the Elixir implementation", async () => {
  const priv = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_a));

  const got = await E2EE.pairwiseKey(
    priv,
    hex(vectors.public_b),
    vectors.room,
    vectors.epoch,
    vectors.from,
    vectors.to
  );

  assert.strictEqual(hexOut(got), vectors.pairwise_key);
});

Deno.test("vectors: pairwiseKey is symmetric", async () => {
  const privA = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_a));
  const privB = await E2EE.importPrivateKey(hex(vectors.rfc7748_private_b));

  const ab = await E2EE.pairwiseKey(privA, hex(vectors.public_b), vectors.room, vectors.epoch, vectors.from, vectors.to);
  const ba = await E2EE.pairwiseKey(privB, hex(vectors.public_a), vectors.room, vectors.epoch, vectors.to, vectors.from);

  assert.deepStrictEqual(ab, ba);
  assert.strictEqual(hexOut(ab), vectors.pairwise_key);
});

Deno.test("vectors: openGroupKey opens the blob the Elixir side sealed", async () => {
  const pairwise = hex(vectors.pairwise_key);
  const wire = E2EE.decodeSealed(vectors.sealed_wire_b64);

  const opened = await E2EE.openGroupKey(
    wire,
    pairwise,
    vectors.room,
    vectors.epoch,
    vectors.from,
    vectors.to
  );

  assert.strictEqual(hexOut(opened), vectors.group_key);
});

Deno.test("vectors: deriveFrameKey matches the Elixir implementation", async () => {
  const groupKey = hex(vectors.group_key);

  for (const [counter, expected] of [
    [0, vectors.frame_key_0],
    [1, vectors.frame_key_1]
  ]) {
    const raw = await E2EE.deriveFrameKey(groupKey, vectors.epoch, counter);
    assert.strictEqual(hexOut(raw), expected, `frame key for counter ${counter}`);
  }
});

Deno.test("vectors: the protocol description in the fixture matches this module", () => {
  // Guards against a fixture regenerated with different labels while the client
  // stayed on the old ones — the failure mode the vectors exist to prevent.
  assert.ok(vectors.protocol.pairwise.includes(E2EE.CONSTANTS.LABEL_PAIRWISE));
  assert.ok(vectors.protocol.seal.includes(E2EE.CONSTANTS.LABEL_GROUP));
  assert.ok(vectors.protocol.frame.includes(E2EE.CONSTANTS.LABEL_FRAME));
  assert.strictEqual(E2EE.CONSTANTS.SEALED_BYTES, 60);
});

// ---------------------------------------------------------------------------
// 2. Sealing: round-trip, AAD binding, tampering
// ---------------------------------------------------------------------------

async function pair(roomId, epoch) {
  const a = await E2EE.generateKeypair();
  const b = await E2EE.generateKeypair();

  const aKey = await E2EE.pairwiseKey(a.privateKey, b.publicKey, roomId, epoch, "alice", "bob");
  const bKey = await E2EE.pairwiseKey(b.privateKey, a.publicKey, roomId, epoch, "bob", "alice");

  return { a, b, aKey, bKey };
}

Deno.test("seal/open round-trips the room key", async () => {
  const { aKey, bKey } = await pair("room-1", 0);
  const groupKey = E2EE.randomGroupKey();

  const wire = await E2EE.sealGroupKey(groupKey, aKey, "room-1", 0, "alice", "bob");
  assert.strictEqual(wire.length, 60);
  assert.deepStrictEqual(aKey, bKey, "both sides must derive the same pairwise key");

  const opened = await E2EE.openGroupKey(wire, bKey, "room-1", 0, "alice", "bob");
  assert.deepStrictEqual(opened, groupKey);
});

Deno.test("AAD rejects a blob replayed into another room, epoch or direction", async () => {
  const { aKey, bKey } = await pair("room-1", 0);
  const wire = await E2EE.sealGroupKey(E2EE.randomGroupKey(), aKey, "room-1", 0, "alice", "bob");

  await assert.rejects(E2EE.openGroupKey(wire, bKey, "room-2", 0, "alice", "bob"), /operation failed|decrypt/i);
  await assert.rejects(E2EE.openGroupKey(wire, bKey, "room-1", 1, "alice", "bob"), /operation failed|decrypt/i);
  await assert.rejects(E2EE.openGroupKey(wire, bKey, "room-1", 0, "bob", "alice"), /operation failed|decrypt/i);
});

Deno.test("a tampered sealed blob does not open", async () => {
  const { aKey, bKey } = await pair("room-1", 0);
  const wire = await E2EE.sealGroupKey(E2EE.randomGroupKey(), aKey, "room-1", 0, "alice", "bob");

  const tampered = Uint8Array.from(wire);
  tampered[30] ^= 0xff; // flip a ciphertext bit

  await assert.rejects(E2EE.openGroupKey(tampered, bKey, "room-1", 0, "alice", "bob"), /operation failed|decrypt/i);
});

Deno.test("the wrong pairwise key does not open a blob", async () => {
  const { aKey } = await pair("room-1", 0);
  const other = await pair("room-1", 0);

  const wire = await E2EE.sealGroupKey(E2EE.randomGroupKey(), aKey, "room-1", 0, "alice", "bob");
  await assert.rejects(E2EE.openGroupKey(wire, other.bKey, "room-1", 0, "alice", "bob"), /operation failed|decrypt/i);
});

Deno.test("malformed inputs are rejected before any crypto happens", async () => {
  const { aKey } = await pair("room-1", 0);

  await assert.rejects(E2EE.sealGroupKey(new Uint8Array(16), aKey, "r", 0, "a", "b"), RangeError);
  await assert.rejects(E2EE.sealGroupKey(E2EE.randomGroupKey(), new Uint8Array(8), "r", 0, "a", "b"), RangeError);
  await assert.rejects(E2EE.openGroupKey(new Uint8Array(59), aKey, "r", 0, "a", "b"), RangeError);
  await assert.rejects(E2EE.openGroupKey(new Uint8Array(61), aKey, "r", 0, "a", "b"), RangeError);
  assert.throws(() => E2EE.decodeSealed("AAAA"), RangeError);
});

// ---------------------------------------------------------------------------
// 3. Frames: sender attribution and replay
// ---------------------------------------------------------------------------

Deno.test("frames round-trip and are bound to sender, epoch and counter", async () => {
  const groupKey = E2EE.randomGroupKey();
  const frame = new TextEncoder().encode("opus-frame-bytes");

  const key = await E2EE.deriveSenderFrameKey(groupKey, 2, "alice", 7);
  const wire = await E2EE.encryptFrame(key, frame, "room-1", 2, "alice", 7);

  const opened = await E2EE.decryptFrame(key, wire, "room-1", 2, "alice", 7);
  assert.deepStrictEqual(opened, frame);

  // Same counters, different sender: the key differs, so this cannot decrypt.
  const bobKey = await E2EE.deriveSenderFrameKey(groupKey, 2, "bob", 7);
  await assert.rejects(E2EE.decryptFrame(bobKey, wire, "room-1", 2, "alice", 7), /operation failed|decrypt/i);

  // Right key, wrong claimed sender in the AAD.
  await assert.rejects(E2EE.decryptFrame(key, wire, "room-1", 2, "bob", 7), /operation failed|decrypt/i);

  // Right key and sender, wrong counter.
  await assert.rejects(E2EE.decryptFrame(key, wire, "room-1", 2, "alice", 8), /operation failed|decrypt/i);
});

Deno.test("a peer cannot derive another peer's frame key from the group key", async () => {
  const groupKey = E2EE.randomGroupKey();

  const alice = await E2EE.deriveSenderFrameKey(groupKey, 0, "alice", 0);
  const bob = await E2EE.deriveSenderFrameKey(groupKey, 0, "bob", 0);

  assert.notDeepStrictEqual(alice, bob, "sender id must change the derivation");

  const frame = new TextEncoder().encode("forged");
  const wire = await E2EE.encryptFrame(alice, frame, "room-1", 0, "alice", 0);

  // Bob holds the group key, so he can compute his own key — and it does not
  // open Alice's frame. He cannot speak as her.
  await assert.rejects(E2EE.decryptFrame(bob, wire, "room-1", 0, "alice", 0), /operation failed|decrypt/i);
  assert.deepStrictEqual(await E2EE.decryptFrame(alice, wire, "room-1", 0, "alice", 0), frame);
});

Deno.test("ReplayWindow accepts new counters, refuses repeats and ancient ones", () => {
  const w = new E2EE.ReplayWindow(4);

  assert.strictEqual(w.accept(0), true);
  assert.strictEqual(w.accept(1), true);
  assert.strictEqual(w.accept(0), false, "replay");
  assert.strictEqual(w.accept(5), true);
  assert.strictEqual(w.accept(2), true, "2 is still within [5 - 4 + 1, 5]");
  assert.strictEqual(w.accept(5), false, "replay of the highest");
  assert.strictEqual(w.accept(1), false, "1 has fallen out of the window");
  assert.strictEqual(w.highest, 5);

  assert.throws(() => w.accept(-1), RangeError);
  assert.throws(() => w.accept(1.5), RangeError);
});

// ---------------------------------------------------------------------------
// 4. Epoch handling
// ---------------------------------------------------------------------------

Deno.test("KeyEpoch drops key material when the epoch advances", async () => {
  const epoch = new E2EE.KeyEpoch("room-1");
  const groupKey = E2EE.randomGroupKey();

  epoch.setRoomKey(groupKey);
  assert.strictEqual(epoch.hasRoomKey(), true);

  assert.strictEqual(epoch.advanceTo(1), true);
  assert.strictEqual(epoch.hasRoomKey(), false, "a member who left still holds the old key");
  assert.strictEqual(epoch.epoch, 1);
});

Deno.test("KeyEpoch ignores a stale epoch rather than rewinding", async () => {
  const epoch = new E2EE.KeyEpoch("room-1");

  epoch.advanceTo(3);
  assert.strictEqual(epoch.advanceTo(2), false);
  assert.strictEqual(epoch.epoch, 3);
  assert.strictEqual(epoch.advanceTo(3), false);
});

Deno.test("KeyEpoch.rotate produces a fresh keypair and clears the room key", async () => {
  const epoch = new E2EE.KeyEpoch("room-1");
  epoch.setRoomKey(E2EE.randomGroupKey());

  const first = await epoch.rotate();
  const second = await epoch.rotate();

  assert.strictEqual(first.length, 32);
  assert.notDeepStrictEqual(first, second);
  assert.strictEqual(epoch.hasRoomKey(), false);
});

Deno.test("KeyEpoch.frameKey requires a room key for the current epoch", async () => {
  const epoch = new E2EE.KeyEpoch("room-1");
  await assert.rejects(epoch.frameKey("alice", 0), /no room key/);

  epoch.setRoomKey(E2EE.randomGroupKey());
  const key = await epoch.frameKey("alice", 0);
  assert.ok(key);
});
